/**
 * A New Queen
 * -----------
 * Esther, a Jewish orphan in the care of Mordecai, is taken to the king and wins the crown. Stage: a harem court at dawn, young women in myrrh and perfumes, Esther stepping forward; a crown lifted; rose and gold light.
 *
 * Palette 0x1a0e08 → 0x060402 · light: dusk · hero: crown
 *
 * Generated by scripts/add-shot-scenes.mjs from the act data and
 * the mood board in ../../art/. Composition follows the kit in
 * ./esther-kit.js.
 */

import { THREE, createScene, column, throne, crown, person } from './esther-kit.js';

const BG = 0x1a0e08;
const GROUND = 0x060402;

export function build(group) {
    const W = createScene(group, { seed: 4205522159, bg: BG, fogNear: 50, fogFar: 200 });

    /* light — dusk */
    W.lights({ sky: 0x7a5a8c, gnd: 0x3a2a1a, hemi: 0.6, sun: 0xff9a50, sunI: 0.85, sunPos: [45, 12, -18] });

    W.disc([55, 22, -140], 12, 0xff9a50);
    W.disc([55, 22, -150], 20, 0xff7a30, 0.18);
    W.stars(30, 150, [0xd8c8e8, 0xc8b8d8], 0.5);
    W.disc([-60, 40, -150], 30, 0x4a3a5c, 0.25);

    /* ground */
    W.ground(260, 260, 0, 0, 0x060402, { amp: 0.6, j: 0.3, flat: 30, rise: (x, z) => Math.sin(x * 0.05) * Math.cos(z * 0.04) * 1.2 });

    /* palace: columns, banners and the throne */
    for (let i = -2; i <= 2; i++) column(W, group, i * 8, 0, -30, 11, 1.3, 0x060402, { band: 0x140b06 });
    throne(W, group, 0, 0, -24, 1.4, { gold: 0x110905 });

    /* hero: the crown */
    crown(W, group, 0, 1.0, 0, 1.3, { gold: 0x100805 });
    W.disc([0, 4, -10], 4, 0x22120a, 0.3);

    /* figures */
    person(W, group, [-5, 0, 5], { robe: 0xe8dcc0, head: 'crown', collar: 0xe0b040, ry: 0.61, s: 1.10 });

    return W.finish();
}

export default { build };
